const vulns=$input.all().map(i=>i.json);
// Group by environment to find lateral movement potential
const byEnv={};
for(const v of vulns){
  const env=v.environment||'unknown';
  if(!byEnv[env]) byEnv[env]=[];
  byEnv[env].push(v);
}
const attack_paths=[];
for(const [env,evulns] of Object.entries(byEnv)){
  if(evulns.length<2) continue;
  // Network-reachable vulns in same environment = potential chain
  const network_vulns=evulns.filter(v=>v.attack_vector==='NETWORK');
  if(network_vulns.length>=2){
    const critical_assets=network_vulns.filter(v=>v.criticality==='critical');
    const path_score=Math.round(network_vulns.reduce((s,v)=>s+v.composite_score,0)/network_vulns.length);
    attack_paths.push({environment:env,vuln_count:network_vulns.length,
      critical_assets:critical_assets.length,path_score,
      entry_points:network_vulns.slice(0,2).map(v=>({asset:v.hostname,cve:v.cve_id})),
      blast_radius:critical_assets.map(a=>a.hostname).join(', ')||'No critical assets in path',
      severity:path_score>=75?'Critical':path_score>=55?'High':'Medium'});
  }
}
attack_paths.sort((a,b)=>b.path_score-a.path_score);
return[{json:{total_vulns:vulns.length,attack_paths,critical_paths:attack_paths.filter(p=>p.severity==='Critical').length,
  generated_at:new Date().toISOString()}}];

const data=$('Identify Attack Chains').first().json;
const ai=$input.first().json;
const brief=ai.content?.[0]?.text||'Attack path analysis complete. See Jira for details.';
return[{json:{...data,executive_brief:brief}}];

